export const BODY: string = "\n<p>قد تبدو صورة مثالية على شاشتك وما زالت تفشل في اللحظة التي ترفعها فيها: سوق يرفضها لأنها صغيرة جدًا، أو مطبعة تقصها بشكل غير متوقع، أو موقع يمدها ضبابية.</p>\n<p>السبب دائمًا تقريبًا الأبعاد: العرض والارتفاع بالبكسلات: معظم الناس لا يراجعونها أبدًا حتى ينكسر شيء، وحينها يكون الموعد النهائي ضيقًا أصلًا.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصور</a> من CompressMyPic، وماذا يعني كل رقم في تقريره، وكيف تستخدمه لاكتشاف مشاكل الحجم قبل أن تصل إلى عملائك.</p>\n<h2 id=\"what-is-a-dimensions-checker\">ما فاحص أبعاد الصور؟</h2>\n<p>فاحص أبعاد الصور يقرأ العرض والارتفاع بالبكسلات لصورك ويعرضها في جدول واضح: يعمل مع ملفات منفردة ومع دفعات كاملة تُسقط دفعة واحدة.</p>\n<p>تقبل الأداة ملفات JPG وPNG وWebP وGIF وBMP وHEIC وSVG، حتى 20 MB لكل ملف: تقرأ الأبعاد الحقيقية المحفوظة داخل كل ملف، لا الحجم الذي يخمنه نظام تشغيلك. وأبعد من العرض والارتفاع، يشمل التقرير النسبة والميغابكسلات وحجم الملف وإن كانت الصورة شفافة: ويحسب أيضًا حجم الطباعة عند 300 DPI لكل صورة.</p>\n<p>وتُعالج كلها محليًا في متصفحك: صورك لا تُرفع أبدًا إلى أي خادم، فتبقى صور منتجات غير منشورة وإعلانات سرية خاصة.</p>\n<h2 id=\"pixels-width-and-height\">البكسلات والعرض والارتفاع موضحة</h2>\n<p>الصورة شبكة بكسلات، وأبعادها هي ببساطة عدد أعمدة تلك الشبكة وصفوفها: صورة موصوفة بأنها 1920 في 1080 لها 1920 بكسلًا عرضًا و1080 بكسلًا ارتفاعًا.</p>\n<p>العرض يأتي أولًا دائمًا في الزوج: صورة 1200 في 800 أفقية، بينما صورة 800 في 1200 عمودية، مع أن كلتيهما تحتوي نفس عدد البكسلات. والبكسلات هي الحجم الوحيد الذي يهم على الشاشة: شاشة تعرض بكسل صورة واحدًا لكل بكسل شاشة عند تكبير كامل، فصورة بعرض 400 بكسل لا تستطيع أبدًا ملء مساحة بعرض 800 بكسل دون مد.</p>\n<p>ذلك المد هو ما يعنيه الناس بصورة ضبابية: المتصفح يخترع البكسلات المفقودة، والاختراع يبدو دائمًا أنعم من الصورة الحقيقية.</p>\n<h2 id=\"aspect-ratio-explained\">النسبة موضحة</h2>\n<p>النسبة هي العلاقة بين العرض والارتفاع، مكتوبة كرقمين بينهما نقطتان، مثل 16:9 أو 4:3: تصف شكل الصورة لا حجمها.</p>\n<p>صورة 1920 في 1080 وصورة 1280 في 720 تشتركان في نسبة 16:9، لأن كلتيهما تختزل إلى نفس التناسب: لهما حجمان مختلفان لكن نفس الشكل. ويقارن الفاحص كل صورة بنسب شائعة مثل 16:9 و4:3 و1:1 و3:2 و4:5: ويعرض أيضًا النسبة الدقيقة عندما تقع صورة بين الأشكال القياسية.</p>\n<p>والنسبة مهمة لأن المنصات تقص حسبها: مساحة عمودية في إنستغرام تتوقع 4:5، فصورة 16:9 رُفعت هناك تفقد جانبيها: ومراجعة النسبة أولًا تخبرك إن كانت الصورة تناسب قبل الرفع.</p>\n<h2 id=\"megapixels-explained\">الميغابكسلات موضحة</h2>\n<p>الميغابكسلات تعد العدد الكلي لبكسلات صورة، معبرًا عنه بالملايين: تحصل على الرقم بضرب العرض في الارتفاع والقسمة على مليون.</p>\n<p>صورة 4000 في 3000 هي 12 ميغابكسلًا، لأن 4000 في 3000 هي 12,000,000 بكسل: وصورة 1920 في 1080 نحو 2.1 ميغابكسل. ويستخدم مصنعو الكاميرات الميغابكسلات كرقم رئيسي، لكن ذلك يخفي الشكل: بانوراما 12 ميغابكسلًا ومربع 12 ميغابكسلًا لهما نفس عدد البكسلات وأبعاد مختلفة جدًا.</p>\n<p>وللطباعة، الميغابكسلات دليل تقريبي لكم حجم تستطيع الطباعة: ملف 12 ميغابكسلًا يُطبع جيدًا بحجم A4، بينما ملف 2 ميغابكسل يبدأ في النعومة عند ذلك الحجم.</p>\n<h2 id=\"batch-checking\">مراجعة دفعة: صور كثيرة معًا</h2>\n<p>مراجعة الصور واحدة واحدة بطيئة عندما يكون لديك كتالوج منتجات أو جلسة تصوير للتحقق: فاحص الأبعاد يقبل دفعات كاملة في إسقاط واحد.</p>\n<p>اسحب مجلدًا أو مجموعة ملفات إلى الأداة وسيبني جدولًا بكل صورة: كل صف يُظهر اسم الملف والأبعاد والنسبة والميغابكسلات وحجم الملف والشفافية وحجم الطباعة. وتستطيع إضافة دفعات أكثر إلى نفس الجدول بعدها: إذا وصل مجلد ثانٍ بعد الأول، أسقطه وتنضم الصفوف الجديدة إلى التقرير الموجود بدل استبداله.</p>\n<p>وإذا تعذر قراءة ملف في دفعة كبيرة، تعلّم الأداة ذلك الملف كخطأ وتستمر: بقية الدفعة تُراجع مع ذلك، فملف تالف لا يحجب العملية كلها أبدًا.</p>\n<h2 id=\"min-width-min-height-validator\">مدقق الحد الأدنى للعرض والارتفاع</h2>\n<p>كثير من المنصات تنشر أحجامًا دنيا بالبكسلات: أمازون وإتسي وشوبيفاي ترفض صور منتج تحت عرض معين، والرقم الدقيق يتغير حسب المنصة.</p>\n<p>يشمل الفاحص تحققًا من حد أدنى للعرض وحد أدنى للارتفاع: تكتب الأرقام التي تطلبها منصتك وتعلم الأداة كل صورة لا تصل. وصورة معلّمة ليست بالضرورة غير قابلة للاستخدام، لكنها تحتاج انتباهًا: تستطيع تكبيرها، مع أن ذلك سيلطّفها، أو تستطيع العودة إلى الأصل وتصديره بحجم أكبر.</p>\n<p>والمدقق مفيد أيضًا داخل فريق: اتفقوا على حد أدنى مرة واحدة واكتبوه في الأداة، وكل دفعة ستُحكم بنفس المعيار بدل الحكم بالعين.</p>\n<h2 id=\"print-size-at-300-dpi\">حجم الطباعة عند 300 DPI</h2>\n<p>يشمل التقرير عمود \"طباعة عند 300 DPI\"، الذي يحوّل الأبعاد بالبكسلات إلى بوصات مادية بجودة طباعة: يجيب عن سؤال كم حجم تستطيع الطباعة.</p>\n<p>الحساب بسيط: اقسم العرض بالبكسلات على 300 للحصول على العرض القابل للطباعة بالبوصات: صورة بعرض 3000 بكسل تُطبع بعرض 10 بوصات عند 300 DPI. وعند 150 DPI تُطبع نفس الصورة بضعف الحجم، لكن بتفصيل أنعم بوضوح: رقم 300 DPI هو الرقم الآمن لكتيبات وكتب وتغليف منتج.</p>\n<p>ويمنع هذا العمود خطأ شائعًا: إرسال صورة بحجم ويب للطباعة: صورة 1200 بكسل تبدو جيدة على الشاشة تُطبع فقط بعرض 4 بوصات عند 300 DPI، صغيرة جدًا لمعظم الاستخدامات. وإذا احتجت تغيير DPI صورة، استخدم <a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI الصور</a>.</p>\n<h2 id=\"transparency-detection\">اكتشاف الشفافية: قنوات ألفا</h2>\n<p>بعض الصور تحمل قناة شفافية، تسمى ألفا، تتيح رؤية ما خلفها في بعض الأجزاء: الشعارات والأيقونات غالبًا تحتاجها، بينما الصور لا تحتاجها.</p>\n<p>يكتشف الفاحص إن كان PNG أو WebP يحمل فعلًا قناة ألفا: ذلك مهم لأن ملفًا قد يُحفظ كـPNG وما زال معتمًا تمامًا، بلا شفافية. ومعرفة هذا تمنع إحراجًا: شعار يبدو شفافًا في محررك لكنه معتم فعلًا سيُظهر مربعًا أبيض عندما يوضع على خلفية ملونة.</p>\n<p>وإذا احتجت تغيير الشفافية، حوّل الملف كما ينبغي: حفظ JPG كـPNG لا يضيف شفافية، وسيخبرك الفاحص قبل أن تكتشف ذلك على الموقع.</p>\n<h2 id=\"csv-and-json-export\">كيف تصدّر التقرير: CSV وJSON</h2>\n<p>المراجعة هي نصف العمل فقط؛ والنصف الآخر مشاركة النتائج: تصدر الأداة الجدول كله كـCSV أو JSON بنقرة واحدة.</p>\n<p>يشمل تصدير CSV أعمدة اسم الملف والأبعاد والنسبة والميغابكسلات وحجم الملف والشفافية وحجم الطباعة: يفتح مباشرة في جدول بيانات للفرز والتصفية. ويحمل تصدير JSON نفس البيانات في صيغة منظمة للمطورين: إنه الخيار الصحيح عندما يغذي التقرير سكربتًا أو سير محتوى أو لوحة جودة.</p>\n<p>صدّر قبل إغلاق التبويب: الجدول يعيش فقط في متصفحك، وتحديث يمسحه: وCSV محفوظ هو السجل الذي يستطيع فريقك العودة إليه.</p>\n<h2 id=\"svg-intrinsic-dimensions\">ملفات SVG والأبعاد الجوهرية</h2>\n<p>رسوم SVG هي متجهات لا بكسلات، فحجمها يعمل بشكل آخر: SVG له أبعاد جوهرية معرفة بسمات العرض والارتفاع وviewBox، والفاحص يقرأها.</p>\n<p>هذا مفيد لأن SVG قد يُقاس إلى أي حجم دون فقدان حدة: أبعاده الجوهرية تخبرك الحجم الذي قصده المصمم، لا حدًا لكم حجم تستطيع الوصول إليه. واحذر SVG التي لها viewBox لكن بلا عرض ولا ارتفاع: لها نسبة لكن بلا حجم ثابت، وسيعرض الفاحص النسبة بينما يشير إلى عدم وجود أبعاد مطلقة.</p>\n<p>وللشعارات والأيقونات، قراءة SVG تؤكد النسب المقصودة: إذا لم تطابق نسبة viewBox ما يتوقعه تصميمك، فالأيقونة ستتشوه أو تترك فجوات.</p>\n<h2 id=\"platform-requirements\">متطلبات منصات شائعة</h2>\n<p>كل منصة لها قواعد أبعادها الخاصة، وتتغير كثيرًا: الجدول التالي نقطة بداية، لكن أكد الأرقام الحالية على المنصة نفسها دائمًا قبل الرفع.</p>\n<p>أسواق مثل أمازون وإتسي تريد صور منتج كبيرة، مربعة أو شبه مربعة، غالبًا 1000 بكسل على الأقل في الجانب الأطول: صور أصغر لا تمر بتحققها. وكل منصة اجتماعية تريد شكلها الخاص: مربع يعمل لمنشور خلاصة، وعمودي 4:5 يملأ شاشة الهاتف أفضل، وأفقي 16:9 ينفع لمصغرة فيديو.</p>\n<p>وخدمات الطباعة تريد أكبر عدد بكسلات تستطيع منحه: هدف 300 DPI يعني أن طباعة صفحة كاملة تحتاج نحو 2500 في 3300 بكسلًا، أكثر بكثير من صورة ويب نموذجية.</p>\n<h2 id=\"fixing-images-that-fail\">كيف تصلح صورًا لا تمر بالمراجعة</h2>\n<p>صورة لا تمر غالبًا لها واحدة من ثلاث مشاكل: صغيرة جدًا أو نسبتها خطأ أو صيغتها لا تنفع للمهمة: ولكل منها حل مختلف.</p>\n<p>صغيرة جدًا هي الأصعب إصلاحًا: التكبير يضيف بكسلات لم تكن هناك أبدًا، فالنتيجة أنعم من أصل عالي الدقة حقيقي: عد إلى الملف المصدر كلما استطعت. ونسبة خطأ تُصلح بالقص: استخدم <a href=\"/ar/qass-as-suwar/\">قصاص الصور</a> لقص الصورة إلى النسبة التي تريدها منصتك، مع إبقاء الشخص ممركزًا والتفاصيل المهمة داخل الإطار.</p>\n<p>وصيغة خطأ تُصلح بالتحويل: صورة محفوظة كـPNG قد تُحوّل إلى JPG للويب، وشعار محفوظ كـJPG يجب أن يُحوّل إلى PNG لتبقى حوافه نظيفة.</p>\n<h2 id=\"dimensions-checker-vs-resizer\">فاحص الأبعاد مقابل مغير حجم الصور</h2>\n<p>الفاحص ومغير الحجم أداتان رفيقتان لا منافستان: الفاحص يخبرك ما حجم صورة، ومغير الحجم يغيّره عندما تكون الإجابة خطأ.</p>\n<p>استخدم الفاحص أولًا، كخطوة تشخيص: يخبرك أي صور في دفعة تفشل وبكم، فتغيّر حجم فقط التي تحتاجه. واستخدم <a href=\"/ar/taghyir-hajm-as-suwar/\">مغير حجم الصور</a> بعدها، فقط على الملفات المعلّمة: تغيير حجم الدفعة كلها يضيع وقتًا وقد يضر صورًا كانت صحيحة أصلًا.</p>\n<p>ثم مرّر الفاحص مجددًا على الملفات المغيرة الحجم: التمريرة الثانية تؤكد أن الإصلاح نجح وتعطيك تقريرًا نهائيًا للأرشفة مع المشروع.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: معالجة دفعة في متصفحك</h2>\n<p>دفعة صور منتج قد تشمل أصنافًا غير منشورة، وإعلان قد يشمل أسعارًا ليست عامة بعد: رفع تلك الملفات إلى خادم خطر.</p>\n<p>يقرأ الفاحص كل ملف محليًا: المتصفح يفتح كل صورة ويقيسها ويبني الجدول دون إرسال بايت واحد إلى أي مكان. وهذا يعني أيضًا أنه لا حد يومي ولا رسوم: تستطيع مراجعة ألف صورة في جلسة، والتكلفة الوحيدة هي الوقت الذي يستغرقه حاسوبك في قراءتها.</p>\n<p>وللفرق التي تتعامل مع مواد سرية، المعالجة المحلية هي الميزة التي تجعل الأداة قابلة للاستخدام: بلا رفع لا توجد أي نسخة من الملفات خارج جهازك.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم فاحص أبعاد الصور</h2>\n<p>افتح <a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصور</a> وأسقط صورك في منطقة الرفع: وتستطيع أيضًا لصق صورة من الحافظة مباشرة للتحقق من دقتها بالبكسلات في ثوانٍ.</p>\n<p>يمتلئ الجدول مع قراءة كل ملف: راجع أعمدة الأبعاد والنسبة والميغابكسلات أولًا، ثم انظر إلى أعمدة حجم الطباعة والشفافية للتفاصيل. واكتب قيم الحد الأدنى للعرض والارتفاع إذا طلبتها منصتك: الصفوف المعلّمة تُرى بوضوح، فتستطيع رؤية أي ملفات تحتاج عملًا بالضبط.</p>\n<p>صدّر التقرير كـCSV أو JSON عندما تنتهي، واقرأ الخطوات العملية في <a href=\"/ar/blog/kayfiyya-fahs-abad-as-sura/\">كيف تفحص أبعاد صورة</a> أو المقارنة في <a href=\"/ar/blog/al-abad-vs-al-diqqa-vs-hajm-al-malaf/\">الأبعاد مقابل الدقة مقابل حجم الملف موضحة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين أبعاد صورة ودقتها؟","answer":"الأبعاد هي العرض والارتفاع بالبكسلات، مثل 1920 في 1080: والدقة هي الكثافة، غالبًا DPI أو PPI، التي تقول كم من تلك البكسلات يناسب بوصة: وصورة قد تكون لها أبعاد كبيرة بدقة منخفضة، أو العكس."},{"question":"كم صورة أستطيع مراجعتها في دفعة؟","answer":"لا حد ثابت في الأداة: تستطيع إسقاط مجلد كامل من الصور ويُبنى الجدول صفًا صفًا: الدفعات الكبيرة جدًا تأخذ وقتًا أطول لأن المتصفح يقرأ كل ملف، لكن لا سقف لعدد الملفات."},{"question":"لماذا تُظهر صورتي أبعادًا مختلفة في تطبيقات مختلفة؟","answer":"بعض التطبيقات تُظهر الأبعاد بالبكسلات بينما أخرى تُظهر الأبعاد بعد تطبيق قيمة DPI أو عامل قياس شاشة: يقرأ الفاحص الأبعاد الحقيقية بالبكسلات المحفوظة داخل الملف، فثق برقمه."},{"question":"هل يستطيع الفاحص إخباري إن كانت صورة ستُطبع جيدًا؟","answer":"نعم، عبر عمود \"طباعة عند 300 DPI\": يحوّل الأبعاد بالبكسلات إلى بوصات مادية بجودة طباعة. وإذا كان الحجم المطبوع أصغر مما تحتاج، فالصورة ستبدو ناعمة عند الطباعة بذلك الحجم."},{"question":"هل أحتاج تثبيت أي شيء لمراجعة أبعاد دفعة؟","answer":"لا، يعمل الفاحص في متصفحك، على حاسوب وهاتف، دون تثبيت ولا حساب: أسقط ملفاتك واقرأ الجدول وصدّر التقرير كـCSV أو JSON."},{"question":"ماذا يحدث لصوري بعد مراجعتها؟","answer":"لا شيء، تُقرأ الملفات محليًا في متصفحك ولا تُرفع أبدًا إلى أي مكان: وعند إغلاق التبويب، يُمسح الجدول من الذاكرة، فصدّر تقرير CSV أو JSON أولًا إذا احتجت الاحتفاظ بالنتائج."}];
